    result += source.slice(i, idx) + '((() => ({}))';
    i = idx + needle.length;
    // Skip optional type parameter <...>
    if (source[i] === '<') {
      let depth = 1;
      i++;
      while (i < source.length && depth > 0) {
        if (source[i] === '<') depth++;
        else if (source[i] === '>') depth--;
        i++;
      }
